code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    colored = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0, 3)]
    crosses = {(r, c) for r, c, _ in colored}
    empty = set()
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 0 and grid[r-1][c] == grid[r+1][c] == grid[r][c-1] == grid[r][c+1] == 3:
                empty.add((r, c))
    crosses |= empty
    arms = {(r+dr, c+dc): (r, c) for r, c in crosses for dr, dc in ((-1,0),(1,0),(0,-1),(0,1))}
    empty_cols = {c for r, c in empty}

    # Extend each colored cross along its row and column. Other crosses' arms
    # stop a ray; the source cross's own arms are traversed.
    for r, c, color in colored:
        for dc in (-1, 1):
            x = c + dc
            while 0 <= x < w:
                owner = arms.get((r, x))
                if owner is not None and owner != (r, c):
                    break
                if grid[r][x] not in (0, 3):
                    break
                if grid[r][x] == 0 and x not in empty_cols:
                    out[r][x] = color
                x += dc
        for dr in (-1, 1):
            y = r + dr
            while 0 <= y < h:
                owner = arms.get((y, c))
                if owner is not None and owner != (r, c):
                    break
                if grid[y][c] not in (0, 3):
                    break
                if grid[y][c] == 0:
                    out[y][c] = color
                y += dr
    return out
'''
